#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

use chrono::Utc;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::{fs::{self, OpenOptions}, io::Write, path::{Path, PathBuf}};
use tauri::command;

mod local_bundles;
use local_bundles::BundlePreview;

#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct WreathDriftResult { drift: bool, door_hash: Option<String>, manifest_slot_hash: Option<String>, details: Vec<String> }
#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct WreathVerifyResult { status: String, total: usize, matched: usize }
#[derive(Debug, Serialize, Deserialize, Clone)]
#[serde(rename_all = "camelCase")]
pub(crate) struct CaseEvent { event_id:String, case_id:String, sequence:u64, #[serde(rename="type")] event_type:String, occurred_at:String, actor:String, previous_hash:Option<String>, payload:Value, hash:String }

pub(crate) fn canonical(value:&Value)->Value { match value { Value::Array(xs)=>Value::Array(xs.iter().map(canonical).collect()), Value::Object(map)=>{let mut out=serde_json::Map::new();let mut keys=map.keys().collect::<Vec<_>>();keys.sort();for key in keys{out.insert(key.clone(),canonical(&map[key]));}Value::Object(out)}, other=>other.clone() } }
pub(crate) fn hash_event(event:&CaseEvent)->String { let mut value=serde_json::to_value(event).unwrap();value.as_object_mut().unwrap().remove("hash");format!("{:x}",Sha256::digest(serde_json::to_string(&canonical(&value)).unwrap().as_bytes())) }
fn uuid()->String { uuid::Uuid::new_v4().to_string() }
fn read_events(root:&Path)->Result<Vec<CaseEvent>,String>{let path=root.join("REGISTER-PREVERJANJ.jsonl");let text=match fs::read_to_string(path){Ok(text)=>text,Err(e)if e.kind()==std::io::ErrorKind::NotFound=>return Ok(Vec::new()),Err(e)=>return Err(e.to_string())};let mut out=Vec::new();for(i,line)in text.lines().enumerate(){if line.trim().is_empty(){continue}let row:Value=serde_json::from_str(line).map_err(|e|format!("Register line {}: {e}",i+1))?;if let Some(event)=row.get("case_event"){out.push(serde_json::from_value(event.clone()).map_err(|e|e.to_string())?)}}Ok(out)}
fn append_event(root:&Path,id:&str,kind:&str,actor:&str,payload:Value)->Result<(),String>{let events=read_events(root)?.into_iter().filter(|e|e.case_id==id).collect::<Vec<_>>();if events.is_empty()&&kind!="case.created"{return Err("Case not found".into())}if !events.is_empty()&&kind=="case.created"{return Err("Case already exists".into())}let previous=events.last();let mut event=CaseEvent{event_id:uuid(),case_id:id.into(),sequence:events.len()as u64+1,event_type:kind.into(),occurred_at:Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis,true),actor:actor.into(),previous_hash:previous.map(|e|e.hash.clone()),payload:payload.clone(),hash:String::new()};event.hash=hash_event(&event);let result=if kind=="review.recorded"{payload["outcome"].as_str().unwrap_or("UNVERIFIED")}else{"UNVERIFIED"};let witnesses=payload.get("evidenceIds").cloned().unwrap_or_else(||payload.get("sourcePath").map(|v|json!([v])).unwrap_or_else(||json!([])));let row=json!({"claim_id":format!("CASE-{id}-{:06}",event.sequence),"subject":format!("case:{id}"),"claim":if kind=="case.created"{payload["claim"].as_str().unwrap_or("Case created")}else{"Case event"},"witnesses":witnesses,"method":kind,"result":result,"reviewer":actor,"timestamp":event.occurred_at,"limitations":"Operational record; not proof of identity, truth, legal effect, or delivery.","case_event":event});let mut out=OpenOptions::new().create(true).append(true).open(root.join("REGISTER-PREVERJANJ.jsonl")).map_err(|e|e.to_string())?;writeln!(out,"{row}").map_err(|e|e.to_string())}
fn capture_source(root:&Path,title:&str,body:&str,note:&str)->Result<Value,String>{let manifest_path=root.join("book.workbench.json");let old_manifest=fs::read(&manifest_path).ok();let mut manifest:Value=match &old_manifest{Some(b)=>serde_json::from_slice(b).map_err(|e|e.to_string())?,None=>json!({"manifestVersion":"2","incomingTexts":[],"fragments":[],"insertions":[],"concepts":[]})};let entries=manifest["incomingTexts"].as_array_mut().ok_or("incomingTexts missing")?;let mut n=1;let id=loop{let candidate=format!("incoming-{n:04}");if !entries.iter().any(|e|e["id"].as_str()==Some(candidate.as_str()))&&!root.join(format!("incoming/{candidate}.txt")).exists(){break candidate}n+=1};let relative=format!("incoming/{id}.txt");entries.push(json!({"id":id,"sourcePath":relative,"status":"new","title":title,"note":note}));let source_path=root.join(&relative);if !source_path.starts_with(root){return Err("Source path escapes project root".into())}let seal_path=root.join("book.workbench.seal.json");let old_seal=fs::read(&seal_path).ok();fs::create_dir_all(source_path.parent().unwrap()).map_err(|e|e.to_string())?;let compact=serde_json::to_string(&manifest).map_err(|e|e.to_string())?;let pretty=format!("{}\n",serde_json::to_string_pretty(&manifest).map_err(|e|e.to_string())?);let tx=(||->Result<(),String>{fs::write(&source_path,body).map_err(|e|e.to_string())?;fs::write(&manifest_path,pretty).map_err(|e|e.to_string())?;let mut clock=json!({"sealedAt":Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis,true),"receivedAt":null,"ci":false,"cli":false});if let Some(old)=old_seal.as_ref().and_then(|b|serde_json::from_slice::<Value>(b).ok()){if let Some(head)=old["clock"]["gitHead"].as_str(){clock["gitHead"]=json!(head)}}let seal=json!({"manifestPath":manifest_path.to_string_lossy(),"manifestSha256":format!("{:x}",Sha256::digest(compact.as_bytes())),"receipts":{"manifest":true,"seal":true,"cli":false,"ci":false},"clock":clock});fs::write(&seal_path,format!("{}\n",serde_json::to_string_pretty(&seal).map_err(|e|e.to_string())?)).map_err(|e|e.to_string())})();if let Err(e)=tx{let _=fs::remove_file(source_path);restore_bytes(&manifest_path,old_manifest);restore_bytes(&seal_path,old_seal);return Err(e)}Ok(json!({"id":id,"sourcePath":relative}))}
fn restore_bytes(path:&Path,bytes:Option<Vec<u8>>){match bytes{Some(b)=>{let _=fs::write(path,b);},None=>{let _=fs::remove_file(path);}}}
fn case_value(id:&str,events:Vec<CaseEvent>)->Result<Value,String>{let mut errors=Vec::new();let mut previous=None;for(i,e)in events.iter().enumerate(){if e.sequence!=i as u64+1||e.previous_hash!=previous||e.hash!=hash_event(e){errors.push(format!("Broken chain at {}",i+1))}previous=Some(e.hash.clone())}let first=events.iter().find(|e|e.event_type=="case.created").ok_or("Case creation missing")?;let(mut evidence,mut actions,mut latest_review,mut status)=(Vec::new(),serde_json::Map::new(),None,"UNVERIFIED");for e in &events{match e.event_type.as_str(){"evidence.added"=>evidence.push(json!({"id":e.payload["evidenceId"],"label":e.payload["label"],"source":e.payload["source"],"contentHash":e.payload["contentHash"],"addedBy":e.actor,"eventId":e.event_id})),"review.recorded"=>{latest_review=Some(json!({"reviewer":e.payload["reviewer"],"executor":e.payload["executor"],"outcome":e.payload["outcome"],"scope":e.payload["scope"],"findings":e.payload["findings"],"eventId":e.event_id}));status=e.payload["outcome"].as_str().unwrap_or("INCONCLUSIVE")},"action.created"=>{actions.insert(e.payload["actionId"].as_str().unwrap_or("").into(),json!({"id":e.payload["actionId"],"description":e.payload["description"],"owner":e.payload["owner"],"status":"OPEN","eventId":e.event_id}));},"action.updated"=>if let Some(a)=actions.get_mut(e.payload["actionId"].as_str().unwrap_or("")){a["status"]=e.payload["status"].clone();a["eventId"]=json!(e.event_id)},_=>()}}let mut v=json!({"id":id,"title":first.payload["title"],"claim":first.payload["claim"],"reporter":first.payload["reporter"],"status":status,"createdAt":first.occurred_at,"evidence":evidence,"actions":actions.values().collect::<Vec<_>>(),"events":events,"integrity":{"valid":errors.is_empty(),"errors":errors}});if let Some(review)=latest_review{v["latestReview"]=review}Ok(v)}
fn cases(root:&Path)->Result<Vec<Value>,String>{let events=read_events(root)?;let mut ids=Vec::new();for e in &events{if !ids.contains(&e.case_id){ids.push(e.case_id.clone())}}ids.into_iter().map(|id|case_value(&id,events.iter().filter(|e|e.case_id==id).cloned().collect())).collect()}
fn get_case(root:&Path,id:&str)->Result<Value,String>{cases(root)?.into_iter().find(|v|v["id"].as_str()==Some(id)).ok_or_else(||format!("Case not found: {id}"))}

#[command]fn list_cases(project_root:String)->Result<Vec<Value>,String>{cases(Path::new(&project_root))}
#[command]fn create_case(project_root:String,title:String,claim:String,reporter:String)->Result<Value,String>{if title.trim().is_empty()||claim.trim().is_empty()||reporter.trim().is_empty(){return Err("title, claim, reporter required".into())}let root=Path::new(&project_root);let id=uuid::Uuid::new_v4().to_string();let src=capture_source(root,&format!("Case {id}: claim"),&claim,"Original claim; case intake")?;append_event(root,&id,"case.created",&reporter,json!({"title":title,"claim":claim,"reporter":reporter,"incomingTextId":src["id"],"sourcePath":src["sourcePath"]}))?;get_case(root,&id)}
#[command]fn add_case_evidence(project_root:String,case_id:String,label:String,source:String,content:String,actor:String)->Result<Value,String>{let root=Path::new(&project_root);get_case(root,&case_id)?;let src=capture_source(root,&format!("Case {case_id}: {label}"),&content,&format!("Evidence: {source}"))?;append_event(root,&case_id,"evidence.added",&actor,json!({"evidenceId":uuid::Uuid::new_v4().to_string(),"label":label,"source":source,"incomingTextId":src["id"],"sourcePath":src["sourcePath"],"contentHash":format!("{:x}",Sha256::digest(content.as_bytes()))}))?;get_case(root,&case_id)}
#[command]fn record_case_review(project_root:String,case_id:String,reviewer:String,executor:String,outcome:String,scope:String,findings:Vec<String>)->Result<Value,String>{if reviewer.trim().eq_ignore_ascii_case(executor.trim()){return Err("Reviewer must differ from executor".into())}if !["SUPPORTED","DISPUTED","INCONCLUSIVE"].contains(&outcome.as_str()){return Err("Invalid outcome".into())}let root=Path::new(&project_root);let c=get_case(root,&case_id)?;let ids=c["evidence"].as_array().into_iter().flatten().filter_map(|e|e["id"].as_str()).collect::<Vec<_>>();append_event(root,&case_id,"review.recorded",&reviewer,json!({"reviewer":reviewer,"executor":executor,"outcome":outcome,"scope":scope,"findings":findings,"evidenceIds":ids}))?;get_case(root,&case_id)}
#[command]fn add_case_action(project_root:String,case_id:String,description:String,owner:String,actor:String)->Result<Value,String>{let root=Path::new(&project_root);get_case(root,&case_id)?;append_event(root,&case_id,"action.created",&actor,json!({"actionId":uuid::Uuid::new_v4().to_string(),"description":description,"owner":owner,"status":"OPEN"}))?;get_case(root,&case_id)}
#[command]fn update_case_action(project_root:String,case_id:String,action_id:String,status:String,actor:String)->Result<Value,String>{let root=Path::new(&project_root);let c=get_case(root,&case_id)?;if !c["actions"].as_array().into_iter().flatten().any(|a|a["id"].as_str()==Some(&action_id)){return Err("Action not found".into())}if !["OPEN","DONE"].contains(&status.as_str()){return Err("Invalid status".into())}append_event(root,&case_id,"action.updated",&actor,json!({"actionId":action_id,"status":status}))?;get_case(root,&case_id)}

#[command]fn export_project_backup(project_root:String,destination:String)->Result<BundlePreview,String>{let s=local_bundles::export_project(Path::new(&project_root))?;fs::write(&destination,&s).map_err(|e|e.to_string())?;local_bundles::preview_text(&s)}
#[command]fn preview_backup(bundle_path:String)->Result<BundlePreview,String>{local_bundles::preview_file(Path::new(&bundle_path))}
#[command]fn restore_backup(bundle_path:String,destination:String,overwrite:bool)->Result<BundlePreview,String>{let s=fs::read_to_string(&bundle_path).map_err(|e|e.to_string())?;local_bundles::restore_project(Path::new(&destination),&s,overwrite)}
#[command]fn export_case_bundle(project_root:String,case_id:String,destination:String)->Result<BundlePreview,String>{let s=local_bundles::export_case(Path::new(&project_root),&case_id)?;fs::write(&destination,&s).map_err(|e|e.to_string())?;local_bundles::preview_text(&s)}
#[command]fn preview_case_import(bundle_path:String)->Result<BundlePreview,String>{local_bundles::preview_file(Path::new(&bundle_path))}
#[command]fn import_case_bundle(project_root:String,bundle_path:String)->Result<BundlePreview,String>{local_bundles::import_case(Path::new(&project_root),&fs::read_to_string(bundle_path).map_err(|e|e.to_string())?)}

#[command]fn read_manifest(project_root:String)->Result<Value,String>{let root=PathBuf::from(project_root);let path=root.join("book.workbench.json");match fs::read_to_string(&path){Ok(s)=>serde_json::from_str(&s).map_err(|e|e.to_string()),Err(e)if e.kind()==std::io::ErrorKind::NotFound=>{fs::create_dir_all(&root).map_err(|e|e.to_string())?;let m=json!({"manifestVersion":"2","incomingTexts":[],"fragments":[],"insertions":[],"concepts":[]});let compact=serde_json::to_string(&m).map_err(|e|e.to_string())?;fs::write(&path,format!("{}\n",serde_json::to_string_pretty(&m).map_err(|e|e.to_string())?)).map_err(|e|e.to_string())?;let seal=json!({"manifestPath":path.to_string_lossy(),"manifestSha256":format!("{:x}",Sha256::digest(compact.as_bytes())),"receipts":{"manifest":true,"seal":true,"cli":false,"ci":false},"clock":{"sealedAt":Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis,true),"receivedAt":null,"ci":false,"cli":false}});fs::write(root.join("book.workbench.seal.json"),format!("{}\n",serde_json::to_string_pretty(&seal).map_err(|e|e.to_string())?)).map_err(|e|e.to_string())?;Ok(m)},Err(e)=>Err(e.to_string())}}
#[command]fn verify_manifest(project_root:String)->Result<Value,String>{let m=read_manifest(project_root)?;let mut errors=Vec::new();if m["manifestVersion"].as_str()!=Some("2"){errors.push("manifestVersion must be 2".into())}for k in ["incomingTexts","fragments","insertions"]{if !m[k].is_array(){errors.push(format!("{k} must be array"))}}Ok(json!({"isValid":errors.is_empty(),"errors":errors}))}
#[command]fn read_seal(project_root:String)->Result<Option<Value>,String>{match fs::read_to_string(Path::new(&project_root).join("book.workbench.seal.json")){Ok(s)=>serde_json::from_str(&s).map(Some).map_err(|e|e.to_string()),Err(e)if e.kind()==std::io::ErrorKind::NotFound=>Ok(None),Err(e)=>Err(e.to_string())}}
#[command]fn verify_wreath(project_root:String)->Result<WreathVerifyResult,String>{let root=Path::new(&project_root);let text=match fs::read_to_string(root.join("LICENSE-MANIFEST")){Ok(x)=>x,Err(_)=>return Ok(WreathVerifyResult{status:"UNVERIFIED".into(),total:0,matched:0})};let m:Value=serde_json::from_str(&text).map_err(|e|e.to_string())?;let items=m["items"].as_array().or_else(||m["files"].as_array()).ok_or("items/files missing")?;let(mut total,mut matched)=(0,0);for item in items{let p=item["path"].as_str().unwrap_or("");if !p.starts_with("LICENSE")||p=="LICENSE-MANIFEST"{continue}let rel=Path::new(p);if rel.is_absolute()||rel.components().any(|c|!matches!(c,std::path::Component::Normal(_))){continue}total+=1;if let Ok(bytes)=fs::read(root.join(rel)){let size=item["size_bytes"].as_u64().or_else(||item["size"].as_u64()).unwrap_or(0);if bytes.len()as u64==size&&format!("{:x}",Sha256::digest(bytes))==item["sha256"].as_str().unwrap_or(""){matched+=1}}}let status=if total==0{"UNVERIFIED"}else if total==matched{"PASS"}else{"FAIL"};Ok(WreathVerifyResult{status:status.into(),total,matched})}
#[command]fn detect_drift(project_root:String)->Result<WreathDriftResult,String>{let root=Path::new(&project_root);let hash=fs::read(root.join("LICENSE.md")).ok().map(|b|format!("{:x}",Sha256::digest(b)));let text=fs::read_to_string(root.join("LICENSE-MANIFEST")).unwrap_or_default();let m:Value=serde_json::from_str(&text).unwrap_or(Value::Null);let items=m["items"].as_array().or_else(||m["files"].as_array());let slot=items.and_then(|a|a.iter().find(|e|e["path"]=="LICENSE.md")).and_then(|e|e["sha256"].as_str()).map(str::to_owned);let drift=hash!=slot;Ok(WreathDriftResult{drift,door_hash:hash,manifest_slot_hash:slot,details:if drift{vec!["LICENSE.md hash differs from manifest".into()]}else{vec![]}})}
#[cfg(test)]mod tests{use super::*;#[test]fn bundle_case_roundtrip_and_integrity(){let root=std::env::temp_dir().join(format!("bundle-test-{}",uuid::Uuid::new_v4()));let target=std::env::temp_dir().join(format!("bundle-target-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&root).unwrap();fs::create_dir_all(&target).unwrap();let result=(||->Result<(),String>{let r=root.to_string_lossy().to_string();let c=create_case(r.clone(),"Case".into(),"Claim".into(),"Reporter".into())?;let id=c["id"].as_str().unwrap();add_case_evidence(r.clone(),id.into(),"Evidence".into(),"Local".into(),"Text".into(),"Reporter".into())?;let b=local_bundles::export_case(&root,id)?;assert!(local_bundles::preview_text(&b)?.valid);let p=local_bundles::import_case(&target,&b)?;assert_eq!(p.case_count,1);let backup=local_bundles::export_project(&root)?;assert!(local_bundles::preview_text(&backup)?.valid);local_bundles::restore_project(&target,&backup,true)?;assert!(local_bundles::import_case(&target,&b).is_err());assert!(local_bundles::restore_project(&target,&backup,false).is_err());let tampered=backup.replace("book.workbench.json","changed.json");assert!(!local_bundles::preview_text(&tampered)?.valid);Ok(())})();let _=fs::remove_dir_all(root);let _=fs::remove_dir_all(target);result.unwrap();}}
fn main(){tauri::Builder::default().plugin(tauri_plugin_log::Builder::default().build()).plugin(tauri_plugin_dialog::init()).plugin(tauri_plugin_fs::init()).invoke_handler(tauri::generate_handler![read_manifest,verify_manifest,read_seal,verify_wreath,detect_drift,list_cases,create_case,add_case_evidence,record_case_review,add_case_action,update_case_action,export_project_backup,preview_backup,restore_backup,export_case_bundle,preview_case_import,import_case_bundle]).run(tauri::generate_context!()).expect("error building desktop app")}
